function t($i,$h,$s,$f,$fm,$j){return'<div class="interactive-wrapper"><div class="card shadow-sm border-0 mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#eef2ff"><i class="'.$i.' text-primary"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">'.$h.'</h5><p class="text-muted small mb-0">'.$s.'</p></div></div><button class="btn btn-sm rounded-pill px-3" id="btn-reset" style="background:#f1f5f9;font-weight:600"><i class="fas fa-undo me-1"></i>Reset</button></div></div><div class="px-4 pb-4" style="overflow-x:auto">'.$f.'<div class="mt-4 text-center"><button class="btn btn-primary btn-lg rounded-pill px-5 shadow-sm" id="btn-calc" style="min-width:260px;max-width:100%"><i class="fas fa-calculator me-2"></i>Calculate</button></div><div class="mt-3 p-3 rounded-4 border" style="background:#f8fafc"><p class="mb-0 small text-muted"><i class="fas fa-info-circle text-primary me-2"></i>'.$fm.'</p></div></div></div><div id="res" class="card shadow-sm border-0 d-none mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#ecfdf5"><i class="fas fa-check-circle text-success"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Result</h5></div></div><button class="btn btn-success btn-sm rounded-pill px-4 shadow-sm" id="btn-copy"><i class="fas fa-copy me-1"></i>Copy</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="p-4 rounded-4 bg-light border text-center mb-3"><div class="small fw-bold text-uppercase text-muted mb-1">RESULT</div><div class="display-4 fw-bold text-dark" id="out-main">—</div><div class="small text-muted fw-bold" id="out-unit"></div></div><div id="out-detail" class="row g-3 mb-3"></div><div class="p-4 rounded-4 bg-light border"><h6 class="fw-bold mb-2 small text-uppercase text-muted"><i class="fas fa-lightbulb text-warning me-2"></i>Insights</h6><div id="out-ins" class="small"></div></div></div></div></div><style>.form-control-lg,.form-select-lg{border:1.5px solid #e2e8f0;border-radius:12px;font-size:1.05rem;padding:.75rem 1rem}.form-control:focus,.form-select:focus{border-color:#4f46e5;box-shadow:0 0 0 4px rgba(79,70,229,.1)}</style><script>'.$j.'</script>';}

