file_put_contents($dir.'ph-poh-calculator.blade.php',t('fas fa-vial','pH pOH Calculator','Full pH/pOH/[H⁺]/[OH⁻] interconversion','<div class="row g-3"><div class="col-md-6"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Input Type</label><select id="in-mode" class="form-select form-select-lg"><option value="ph">pH</option><option value="poh">pOH</option><option value="h">[H⁺] mol/L</option><option value="oh">[OH⁻] mol/L</option></select></div><div class="col-md-6"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Value</label><input type="number" id="in-v" class="form-control form-control-lg" value="7" step="any"></div></div>','<b>Relations:</b> pH+pOH=14 | pH=−log[H⁺] | pOH=−log[OH⁻]','document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var m=document.getElementById("in-mode").value,v=parseFloat(document.getElementById("in-v").value),ph,poh,h,oh;if(isNaN(v))return;if(m==="ph"){ph=v;poh=14-v;h=Math.pow(10,-v);oh=Math.pow(10,-poh);}else if(m==="poh"){poh=v;ph=14-v;h=Math.pow(10,-ph);oh=Math.pow(10,-v);}else if(m==="h"){h=v;ph=-Math.log10(v);poh=14-ph;oh=Math.pow(10,-poh);}else{oh=v;poh=-Math.log10(v);ph=14-poh;h=Math.pow(10,-ph);}document.getElementById("out-main").textContent="pH "+ph.toFixed(2)+" | pOH "+poh.toFixed(2);document.getElementById("out-main").style.fontSize="1.8rem";document.getElementById("out-unit").textContent="";document.getElementById("out-detail").innerHTML=\'<div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">pH</div><div class="h5 fw-bold mb-0 text-primary">\'+ph.toFixed(4)+\'</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">pOH</div><div class="h5 fw-bold mb-0 text-info">\'+poh.toFixed(4)+\'</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">[H⁺]</div><div class="h5 fw-bold mb-0 text-danger">\'+h.toExponential(2)+\'</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">[OH⁻]</div><div class="h5 fw-bold mb-0 text-success">\'+oh.toExponential(2)+\'</div></div></div>\';var nat=ph<6.5?"Acidic":ph>7.5?"Basic":"Neutral";document.getElementById("out-ins").innerHTML="<p>Solution is <b>"+nat+"</b>. Kw = [H⁺]×[OH⁻] = "+(h*oh).toExponential(2)+"</p>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-v").value=7;document.getElementById("in-mode").value="ph";document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText(document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\\"fas fa-copy me-1\\"></i>Copy";},2e3);});});'));
