file_put_contents($dir.'chemical-element-lookup.blade.php',t('fas fa-atom','Chemical Element Lookup','Look up element properties, electron configuration','<div class="row g-3"><div class="col-12"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Element Symbol or Name</label><input type="text" id="in-el" class="form-control form-control-lg" value="Carbon" placeholder="e.g. Carbon, Fe, 26"></div></div>','<b>Source:</b> IUPAC Periodic Table 2021','document.addEventListener("DOMContentLoaded",function(){var DB={H:{z:1,w:1.008,name:"Hydrogen",ec:"1s1",g:"Nonmetal"},He:{z:2,w:4.003,name:"Helium",ec:"1s2",g:"Noble gas"},Li:{z:3,w:6.941,name:"Lithium",ec:"[He]2s1",g:"Alkali metal"},C:{z:6,w:12.011,name:"Carbon",ec:"[He]2s2 2p2",g:"Nonmetal"},N:{z:7,w:14.007,name:"Nitrogen",ec:"[He]2s2 2p3",g:"Nonmetal"},O:{z:8,w:15.999,name:"Oxygen",ec:"[He]2s2 2p4",g:"Nonmetal"},Na:{z:11,w:22.990,name:"Sodium",ec:"[Ne]3s1",g:"Alkali metal"},Cl:{z:17,w:35.45,name:"Chlorine",ec:"[Ne]3s2 3p5",g:"Halogen"},Fe:{z:26,w:55.845,name:"Iron",ec:"[Ar]3d6 4s2",g:"Transition metal"},Cu:{z:29,w:63.546,name:"Copper",ec:"[Ar]3d10 4s1",g:"Transition metal"},Au:{z:79,w:196.97,name:"Gold",ec:"[Xe]4f14 5d10 6s1",g:"Transition metal"},Ag:{z:47,w:107.87,name:"Silver",ec:"[Kr]4d10 5s1",g:"Transition metal"}};function find(q){q=q.trim();for(var k in DB){if(k.toLowerCase()===q.toLowerCase()||DB[k].name.toLowerCase()===q.toLowerCase()||DB[k].z===parseInt(q))return{sym:k,d:DB[k]};}return null;}document.getElementById("btn-calc").addEventListener("click",function(){var r=find(document.getElementById("in-el").value);if(!r){document.getElementById("out-main").textContent="Not found";document.getElementById("out-unit").textContent="Try another element";document.getElementById("out-detail").innerHTML="";document.getElementById("out-ins").innerHTML="";document.getElementById("res").classList.remove("d-none");return;}document.getElementById("out-main").textContent=r.sym+" — "+r.d.name;document.getElementById("out-main").style.fontSize="2rem";document.getElementById("out-unit").textContent=r.d.g;document.getElementById("out-detail").innerHTML=\'<div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Atomic #</div><div class="h5 fw-bold mb-0 text-primary">\'+r.d.z+\'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Weight</div><div class="h5 fw-bold mb-0 text-info">\'+r.d.w+\' u</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Config</div><div class="h5 fw-bold mb-0 text-success" style="font-size:0.85rem">\'+r.d.ec+\'</div></div></div>\';document.getElementById("out-ins").innerHTML="<p>Electron config: <b>"+r.d.ec+"</b></p>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-el").value="Carbon";document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText(document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\\"fas fa-copy me-1\\"></i>Copy";},2e3);});});'));
