file_put_contents($dir.'reaction-yield-calc.blade.php',t('fas fa-chart-line','Reaction Yield Calc','Calculate actual, theoretical, and percent yield','<div class="row g-3"><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Actual Yield (g)</label><input type="number" id="in-a" class="form-control form-control-lg" value="7.2" step="0.01"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Theoretical Yield (g)</label><input type="number" id="in-t" class="form-control form-control-lg" value="10" step="0.01"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Molar Mass Product (g/mol)</label><input type="number" id="in-mm" class="form-control form-control-lg" value="18.015" step="0.001"></div></div>','<b>Formula:</b> %Yield = (Actual/Theoretical) × 100','document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var a=parseFloat(document.getElementById("in-a").value)||0,t=parseFloat(document.getElementById("in-t").value)||0,mm=parseFloat(document.getElementById("in-mm").value)||1;if(t===0)return;var pct=(a/t)*100,molA=a/mm,molT=t/mm;document.getElementById("out-main").textContent=pct.toFixed(2)+"%";document.getElementById("out-unit").textContent="Percent Yield";document.getElementById("out-detail").innerHTML=\'<div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Actual mol</div><div class="h5 fw-bold mb-0 text-primary">\'+molA.toFixed(4)+\'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Theoretical mol</div><div class="h5 fw-bold mb-0 text-info">\'+molT.toFixed(4)+\'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Lost</div><div class="h5 fw-bold mb-0 text-danger">\'+(t-a).toFixed(2)+\' g</div></div></div>\';var ins=["("+a+"/"+t+")×100 = <b>"+pct.toFixed(2)+"%</b>"];if(pct>100)ins.push("⚠ >100% indicates impurities");else if(pct>90)ins.push("Excellent yield");document.getElementById("out-ins").innerHTML=\'<ul class="list-unstyled mb-0">\'+ins.map(function(x){return\'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>\'+x+"</li>";}).join("")+"</ul>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-a").value=7.2;document.getElementById("in-t").value=10;document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText("Yield: "+document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\\"fas fa-copy me-1\\"></i>Copy";},2e3);});});'));
